param([Parameter(Mandatory=$true)][string]$Backup,[string]$EnvironmentFile='')
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;if(!$EnvironmentFile){$EnvironmentFile=Join-Path $root '.env.production'};if(!(Test-Path $Backup)){throw 'Backup file does not exist.'};if((Get-Item $Backup).Length-lt 1024){throw 'Backup is too small to be valid.'};docker cp $Backup chahinaz-pos-production-postgres:/tmp/chahinaz-verify.dump;docker compose --env-file $EnvironmentFile -f (Join-Path $root 'compose.production.yaml') exec -T postgres pg_restore -l /tmp/chahinaz-verify.dump *> $null;$code=$LASTEXITCODE;docker compose --env-file $EnvironmentFile -f (Join-Path $root 'compose.production.yaml') exec -T postgres rm -f /tmp/chahinaz-verify.dump;if($code-ne 0){throw 'pg_restore could not inspect this archive.'};Write-Host 'Backup archive verified.' -ForegroundColor Green
